reviewed_source.ai_accept:
ai_accept = {
	base = 0

	negotiate_alliance_interaction_ai_acceptance = yes

	# Tier Difference 	(+/-)
	# Inheritance 		(+)
	# Opinion 			(+/-)
	# Dynasty Prestige. (+)
	# Different Faith.	(-)
	# Liege is asking 	(+)
	# Dread 			(+)
	# Power difference 	(+/-)
	# Claimants (+/-)
	# Same House (+)
	# Declared war opinion
	# Actor is at war penalty

	modifier = {
		add = 20
		scope:recipient = {
			is_close_family_of = scope:puppet_or_actor
		}
		desc = CLOSE_FAMILY_REASON
	}

	modifier = {
		add = 10
		scope:recipient = {
			NOT = { is_close_family_of = scope:puppet_or_actor }
			is_extended_family_of = scope:puppet_or_actor
		}
		desc = EXTENDED_FAMILY_REASON
	}

	modifier = {
		add = -20
		scope:recipient = {
			NOT = { is_close_or_extended_family_of = scope:puppet_or_actor }
			any_spouse = {
				NOT = { is_close_family_of = scope:puppet_or_actor }
				is_extended_family_of = scope:puppet_or_actor
			}
		}
		desc = DISTANT_FAMILY_CONNECTION_REASON
	}

	modifier = {
		scope:recipient = {
			has_relation_lover = scope:puppet_or_actor
		}
		add = {
			value = 25
		}
		desc = WE_ARE_LOVERS
	}
	modifier = {
		scope:recipient = {
			has_relation_friend = scope:puppet_or_actor
		}
		add = {
			value = 25
		}
		desc = WE_ARE_FRIENDS
	}
	modifier = {
		scope:recipient = {
			is_heir_of = scope:puppet_or_actor
		}
		scope:puppet_or_actor = {
			tier_difference = {
				target = scope:recipient
				value > 0
			}
		}
		add = {
			value = 10
			if = {
				limit = {
					scope:puppet_or_actor = { player_heir = scope:recipient }
				}
				add = 10
			}
		}
		desc = IS_HEIR_REASON
	}
	modifier = {
		add = 20
		desc = FAMILY_BLOOD_BROTHERHOOD_REASON
		scope:puppet_or_actor = {
			has_opinion_modifier = {
				modifier = blood_brother_close_family_opinion
				target = scope:recipient
			}
		}
	}

	# Unity modifiers
	evaluate_action_increasing_house_unity = {
		VALUE = 100
	}

	fp3_struggle_resist_allied_wars_modifier = yes

	# LOW LEGITIMACY
	modifier = {
		desc = "LOW_LEGITIMACY_REASON"
		scope:puppet_or_actor = {
			OR = {
				has_legitimacy_flag = reduced_alliance_acceptance
				has_legitimacy_flag = very_reduced_alliance_acceptance
				has_legitimacy_flag = massively_reduced_alliance_acceptance
			}
		}
		add = {
			value = 0
			if = {
				limit = { scope:puppet_or_actor = { has_legitimacy_flag = reduced_alliance_acceptance } }
				add = -25
			}
			if = {
				limit = { scope:puppet_or_actor = { has_legitimacy_flag = very_reduced_alliance_acceptance } }
				add = -50
			}
			if = {
				limit = { scope:puppet_or_actor = { has_legitimacy_flag = massively_reduced_alliance_acceptance } }
				add = -100
			}
		}
	}

	# HIGH LEGITIMACY
	modifier = {
		desc = "HIGH_LEGITIMACY_REASON"
		scope:puppet_or_actor = {
			OR = {
				has_legitimacy_flag = increased_alliance_acceptance
				has_legitimacy_flag = very_increased_alliance_acceptance
				has_legitimacy_flag = extra_increased_alliance_acceptance
			}
		}
		add = {
			value = 0
			if = {
				limit = { scope:puppet_or_actor = { has_legitimacy_flag = increased_alliance_acceptance } }
				add = 10
			}
			if = {
				limit = { scope:puppet_or_actor = { has_legitimacy_flag = very_increased_alliance_acceptance } }
				add = 25
			}
			if = {
				limit = { scope:puppet_or_actor = { has_legitimacy_flag = extra_increased_alliance_acceptance } }
				add = 50
			}
		}
	}

	# TGP ALLIANCE WITH NF HOUSE HEAD
	modifier = {
		add = 750
		scope:puppet_or_actor = {
			is_house_head = yes
			scope:recipient.house ?= this.house
			any_held_title = { is_noble_family_title = yes }
		}
		desc = JAPANESE_HOUSE_HEAD_ALLIANCE_REASON
	}

	modifier = {
		add = 10
		desc = pam_praised_hunting_alliance_accept_reason
		scope:recipient = {
			exists = var:pam_praised_hunting_alliance_var
			var:pam_praised_hunting_alliance_var = scope:puppet_or_actor
		}
	}
}

reviewed_source.on_accept:
on_accept = {
	scope:puppet_or_actor = {
		trigger_event = char_interaction.0235

		stress_and_fulfillment_impact = {
			shy = minor_stress_impact_gain
		}

		if = {
			limit = {
				scope:hook = yes
				has_usable_hook = scope:recipient
			}
			use_hook = scope:recipient
		}
		if = {
			limit = {
				scope:influence = yes
			}
			change_influence = major_influence_loss
		}
	}

	scope:recipient = {
		custom_tooltip = negotiate_alliance_effect_recipient_tooltip
	}

	#Set up alliance, depending on relation between rulers.
	hidden_effect = {
		#Prioritize marriage between rulers and/or direct blood relation between rulers first.
		if = {
			limit = {
				scope:puppet_or_actor = {
					OR = {
						is_spouse_of = scope:recipient
						is_child_of = scope:recipient
						is_parent_of = scope:recipient
						is_sibling_of = scope:recipient
						is_grandparent_of = scope:recipient
						is_great_grandparent_of = scope:recipient
						is_grandchild_of = scope:recipient
						is_great_grandchild_of = scope:recipient
						is_uncle_or_aunt_of = scope:recipient
						is_nibling_of = scope:recipient
					}
				}
			}
			scope:puppet_or_actor = {
				create_alliance = {
					target = scope:recipient
					allied_through_owner = scope:puppet_or_actor
					allied_through_target = scope:recipient
				}
			}
		}
		#...Then marriage between close family members and either actor or recipient.
		else_if = {
			limit = {
				scope:recipient = {
					any_spouse = {
						OR = {
							is_close_family_of = scope:puppet_or_actor
							is_nibling_of = scope:puppet_or_actor
							is_uncle_or_aunt_of = scope:puppet_or_actor
						}
					}
				}
			}
			scope:recipient = {
				random_spouse = {
					limit = {
						OR = {
							is_close_family_of = scope:puppet_or_actor
							is_nibling_of = scope:puppet_or_actor
							is_uncle_or_aunt_of = scope:puppet_or_actor
						}
					}
					save_scope_as = recipient_spouse
				}
			}
			scope:puppet_or_actor = {
				create_alliance = {
					target = scope:recipient
					allied_through_owner = scope:recipient_spouse
					allied_through_target = scope:recipient
				}
			}
		}
		else_if = {
			limit = {
				scope:puppet_or_actor = {
					any_spouse = {
						OR = {
							is_close_family_of = scope:recipient
							is_nibling_of = scope:recipient
							is_uncle_or_aunt_of = scope:recipient
						}
					}
				}
			}
			scope:puppet_or_actor = {
				random_spouse = {
					limit = {
						OR = {
							is_close_family_of = scope:recipient
							is_nibling_of = scope:recipient
							is_uncle_or_aunt_of = scope:recipient
						}
					}
					save_scope_as = actor_spouse
				}
			}
			scope:puppet_or_actor = {
				create_alliance = {
					target = scope:recipient
					allied_through_owner = scope:puppet_or_actor
					allied_through_target = scope:actor_spouse
				}
			}
		}
		#...And finally marriage between close relatives and close relatives.
		else_if = {
			limit = {
				scope:puppet_or_actor = {
					any_close_family_member = {
						OR = {
							is_child_of = scope:puppet_or_actor
							is_parent_of = scope:puppet_or_actor
							is_sibling_of = scope:puppet_or_actor
						}
						any_spouse = {
							OR = {
								is_child_of = scope:recipient
								is_parent_of = scope:recipient
								is_sibling_of = scope:recipient
							}
						}
					}
				}
			}
			scope:puppet_or_actor = {
				random_close_family_member = {
					limit = {
						OR = {
							is_child_of = scope:puppet_or_actor
							is_parent_of = scope:puppet_or_actor
							is_sibling_of = scope:puppet_or_actor
						}
						any_spouse = {
							OR = {
								is_child_of = scope:recipient
								is_parent_of = scope:recipient
								is_sibling_of = scope:recipient
							}
						}
					}
					save_scope_as = actor_spouse
					random_spouse = {
						limit = {
							OR = {
								is_child_of = scope:recipient
								is_parent_of = scope:recipient
								is_sibling_of = scope:recipient
							}
						}
						save_scope_as = recipient_spouse
					}
				}
			}
			scope:puppet_or_actor = {
				create_alliance = {
					target = scope:recipient
					allied_through_owner = scope:actor_spouse
					allied_through_target = scope:recipient_spouse
				}
			}
		}
		else_if = {
			limit = {
				scope:puppet_or_actor = { has_perk = defensive_negotiations_perk }
			}
			scope:puppet_or_actor = {
				create_alliance = {
					target = scope:recipient
					allied_through_owner = scope:puppet_or_actor
					allied_through_target = scope:recipient
				}
			}
			scope:recipient = { # This opinion modifier controls the interaction, and is removed when breaking the alliance in any way (though on_actions)
				add_opinion = {
					modifier = perk_negotiated_alliance_opinion
					target = scope:puppet_or_actor
				}
			}
		}
		else_if = {
			limit = {
				scope:puppet_or_actor = {
					hostage_oath_of_friendship_trigger = yes
				}
			}
			scope:puppet_or_actor = {
				create_alliance = {
					target = scope:recipient
					allied_through_owner = scope:puppet_or_actor
					allied_through_target = scope:recipient
				}
			}
		}
	}

	add_clan_unity_interaction_effect = {
		CHARACTER = scope:puppet_or_actor
		TARGET = scope:recipient
		VALUE = minor_unity_gain
		DESC = clan_unity_alliance.desc
		REVERSE_NON_HOUSE_TARGET = no
	}
}

reviewed_source.on_decline:
on_decline = {
	scope:puppet_or_actor = {
		trigger_event = char_interaction.0236
	}
	scope:puppet_or_actor = {
		add_opinion = {
			modifier = refused_alliance_opinion
			target = scope:recipient
		}
	}

	add_clan_unity_interaction_effect = {
		CHARACTER = scope:puppet_or_actor
		TARGET = scope:recipient
		VALUE = minor_unity_loss
		DESC = clan_unity_alliance_refusal.desc
		REVERSE_NON_HOUSE_TARGET = no
	}
}
